system.easyEffects:
[On Clash RESULT with CHOICE]
spend (N*2) Charge to create dialog "Charge : Give [Type] Protection":
  slash as "Slash Protection",
  pierce as "Pierce Protection",
  blunt as "Blunt Protection"
  to self;

[On Dialog Answer slash]
proc "Give Self Or Ally: (N*2) Slash Protection next round";

[On Dialog Answer pierce]
proc "Give Self Or Ally: (N*2) Pierce Protection next round";

[On Dialog Answer blunt]
proc "Give Self Or Ally: (N*2) Blunt Protection next round";
